globalThis.PracticeBank=[{"n": 1, "topic": "Genetics", "obj": ["G01"], "stem": "An animal cell copies its DNA normally, but the structures that help organise its spindle are damaged. Which structures are involved?", "options": ["Centrioles", "Mitochondria", "Sugar-phosphate backbones", "Cytoplasm only"], "correct": 0, "why": "Centrioles help organise spindle microtubules in animal cells. Mitochondria support aerobic respiration; they do not organise the spindle.", "figure": null, "marks": 1, "level": "Core"}, {"n": 2, "topic": "Genetics", "obj": ["G02"], "stem": "A researcher labels a short information-carrying section P within a long DNA molecule packaged with proteins as structure Q. Which identification is correct?", "options": ["P is a chromosome; Q is a gene.", "P is a gene; Q is a chromosome.", "P is a nucleus; Q is a nucleotide.", "P is a protein; Q is a base."], "correct": 1, "why": "A gene is a section of DNA; a chromosome consists of a long DNA molecule associated with proteins.", "figure": null, "marks": 1, "level": "Core"}, {"n": 3, "topic": "Genetics", "obj": ["G03"], "stem": "A model nucleotide already contains phosphate and adenine. What must be added to complete one DNA nucleotide?", "options": ["An amino acid", "A second nitrogen-containing base", "Deoxyribose sugar", "A whole chromosome"], "correct": 2, "why": "A DNA nucleotide has phosphate, deoxyribose and one base. Adenine is the base already supplied.", "figure": null, "marks": 1, "level": "Core"}, {"n": 4, "topic": "Genetics", "obj": ["G04"], "stem": "A DNA model unzips without breaking either sugar-phosphate backbone. Which interactions are being disrupted?", "options": ["Covalent bonds along both backbones", "Bonds within every sugar molecule", "Bonds joining amino acids", "Hydrogen bonds between complementary bases"], "correct": 3, "why": "Unzipping separates complementary bases held together by hydrogen bonds; the covalent backbone can remain intact.", "figure": null, "marks": 1, "level": "Core"}, {"n": 5, "topic": "Genetics", "obj": ["G04"], "stem": "Four proposed base counts for complete double-stranded DNA samples are shown below. Which sample is consistent with complementary base pairing?", "options": ["A = 18, T = 22, C = 30, G = 30", "A = 24, T = 24, C = 26, G = 26", "A = 20, T = 30, C = 20, G = 30", "A = 25, T = 15, C = 35, G = 25"], "correct": 1, "why": "Complete double-stranded DNA has equal A and T counts and equal C and G counts. Only B satisfies both conditions.", "figure": null, "marks": 1, "level": "Core"}, {"n": 6, "topic": "Genetics", "obj": ["G05"], "stem": "Which sequence best links inherited information to a protein?", "options": ["Protein shape determines the original DNA base order.", "Chromosome number directly sets amino-acid order.", "DNA base order supplies information for amino-acid order.", "Phosphate groups are joined to make the protein."], "correct": 2, "why": "The base sequence supplies information used to assemble amino acids in a particular order. Proteins are not phosphate chains.", "figure": null, "marks": 1, "level": "Core"}, {"n": 7, "topic": "Genetics", "obj": ["G06"], "stem": "A cell has 4 units of DNA in G1 and 8 units in G2. In which interval did the increase occur?", "options": ["S phase", "Cytokinesis", "Anaphase", "After the two daughter cells separated"], "correct": 0, "why": "DNA replication occurs during S phase, between G1 and G2. The chromosome count does not automatically double when DNA is copied.", "figure": null, "marks": 1, "level": "Core"}, {"n": 8, "topic": "Genetics", "obj": ["G07", "G08"], "stem": "The diagram shows new nuclear envelopes forming around separated chromosome sets. Which phase of mitosis is represented?", "options": ["Prophase", "Metaphase", "Anaphase", "Telophase"], "correct": 3, "why": "The re-formation of two nuclei identifies telophase. In anaphase, chromatids are still separating.", "figure": "telophase", "marks": 1, "level": "Core"}, {"n": 9, "topic": "Genetics", "obj": ["G06", "G07"], "stem": "An animal cell completes nuclear division, but its cytoplasm does not divide. What is the most direct result?", "options": ["Four haploid cells", "One cell containing two nuclei", "Two cells with no nuclei", "One nucleus containing no DNA"], "correct": 1, "why": "Mitosis divides the nucleus; cytokinesis divides the cytoplasm. If cytokinesis fails, a binucleate cell can remain.", "figure": null, "marks": 1, "level": "Core"}, {"n": 10, "topic": "Genetics", "obj": ["G13"], "stem": "A diploid model cell contains one long homologous pair and one short homologous pair. Which set is a normal haploid product?", "options": ["Both long chromosomes only", "Both short chromosomes only", "One long and one short chromosome", "All four chromosomes"], "correct": 2, "why": "A haploid product receives one member of each homologous pair, not both members of just one pair.", "figure": null, "marks": 1, "level": "Core"}, {"n": 11, "topic": "Genetics", "obj": ["G14"], "stem": "Why would a species fail to maintain its usual chromosome number if unreduced diploid gametes fused every generation?", "options": ["Each offspring would lose all its chromosomes.", "Fertilisation would stop DNA replication.", "Mitosis would halve the chromosome number.", "Fusion would combine two diploid sets rather than two haploid sets."], "correct": 3, "why": "Meiosis reduces chromosome number before fertilisation. Fusion of two diploid gametes would produce a tetraploid zygote in this simple model.", "figure": null, "marks": 1, "level": "Core"}, {"n": 12, "topic": "Genetics", "obj": ["G18"], "stem": "A chromosome display has the expected number of chromosomes and no large visible changes. Which conclusion is justified?", "options": ["Small DNA sequence changes may still be present.", "Every gene must have its usual sequence.", "The person cannot carry a recessive allele.", "All proteins must function normally."], "correct": 0, "why": "A karyotype can reveal chromosome number and some large structural changes, but it cannot rule out small gene-level mutations.", "figure": null, "marks": 1, "level": "Core"}, {"n": 13, "topic": "Genetics", "obj": ["G19"], "stem": "In the typical human XX/XY model, an egg contributes X. Which gamete combination normally forms an XY zygote?", "options": ["X egg + X sperm", "Y egg + Y sperm", "X egg + Y sperm", "X egg + XY sperm"], "correct": 2, "why": "An X-bearing egg and a Y-bearing sperm form XY. This simplified model describes typical chromosomal sex determination, not gender identity.", "figure": null, "marks": 1, "level": "Core"}, {"n": 14, "topic": "Genetics", "obj": ["G21"], "stem": "At one autosomal gene, a parent produces both M-bearing and m-bearing gametes. Which genotype accounts for this?", "options": ["MM", "Mm", "mm", "M only"], "correct": 1, "why": "A heterozygous Mm parent has two different alleles at that gene; segregation produces M or m gametes.", "figure": null, "marks": 1, "level": "Core"}, {"n": 15, "topic": "Genetics", "obj": ["G20", "G21"], "stem": "In a complete-dominance model, a recessive allele is present in a heterozygote. What happens to that allele?", "options": ["It is destroyed by the dominant allele.", "It changes into the dominant allele.", "It cannot enter a gamete.", "It can be transmitted even though the recessive phenotype is not expressed."], "correct": 3, "why": "Dominance concerns phenotype in a heterozygote, not the destruction or transmission of an allele.", "figure": null, "marks": 1, "level": "Core"}, {"n": 16, "topic": "Genetics", "obj": ["G21"], "stem": "In a fictional plant, purple stems (P) are completely dominant to green stems (p). Two heterozygous plants produce four offspring. Which statement correctly interprets the expected 3:1 phenotype ratio?", "options": ["Each offspring has a 3/4 chance of purple stems; four offspring need not include exactly three purple plants.", "Exactly three offspring must be purple and one must be green.", "The fourth offspring must be green if the first three are purple.", "A green offspring changes the probability for the next offspring."], "correct": 0, "why": "A Punnett ratio describes probabilities across independent fertilisations. Small families need not match the expected ratio exactly.", "figure": null, "marks": 1, "level": "Core"}, {"n": 17, "topic": "Genetics", "obj": ["G11"], "stem": "A DNA base substitution is detected, but the cell makes a protein with unchanged amino-acid sequence and function. Which interpretation is best supported?", "options": ["No DNA mutation occurred.", "Every mutation must cause disease.", "This mutation has no detected effect on that protein.", "The cell deliberately chose a useful change."], "correct": 2, "why": "A DNA sequence change is a mutation even when the tested protein is unchanged. Effects depend on the mutation and context.", "figure": null, "marks": 1, "level": "Core"}, {"n": 18, "topic": "Genetics", "obj": ["G11", "G20"], "stem": "A mutation occurs only in a skin cell after UV exposure. Why is that mutation not normally inherited by the person’s children?", "options": ["Skin cells have no chromosomes.", "The altered DNA is not in the gametes forming the children.", "All UV mutations are immediately repaired.", "Recessive alleles cannot be inherited."], "correct": 1, "why": "A somatic mutation confined to skin is not present in the reproductive cells that contribute DNA to the next generation.", "figure": null, "marks": 1, "level": "Core"}, {"n": 19, "topic": "Evolution", "obj": ["E01"], "stem": "Two populations mate in nature and produce offspring that survive but cannot reproduce. Under the biological species concept, which evidence is still missing to classify them as the same species?", "options": ["The parents having the same mass", "The parents living in the same place", "The offspring having the same colour", "The offspring being fertile"], "correct": 3, "why": "The biological species concept requires reproductive compatibility that produces viable, fertile offspring. Survival alone is insufficient.", "figure": null, "marks": 1, "level": "Core"}, {"n": 20, "topic": "Evolution", "obj": ["E02", "E03", "G20"], "stem": "Every winter, individual animals grow thicker coats. Their inherited allele frequencies remain unchanged across generations. What does this observation alone demonstrate?", "options": ["A seasonal individual response, not evidence of genetic evolution", "A new species each winter", "A new mutation in every animal", "Natural selection has removed all variation"], "correct": 0, "why": "A reversible response within an individual is not itself a change in inherited population characteristics across generations.", "figure": null, "marks": 1, "level": "Core"}, {"n": 21, "topic": "Evolution", "obj": ["E05"], "stem": "A variant helps adults survive a harsh season, but those adults leave no offspring. Why might the variant fail to become more common in the next generation?", "options": ["Survival is never relevant to selection.", "The environment must create the allele again.", "The adults did not transmit the variant through reproduction.", "A useful allele must be dominant."], "correct": 2, "why": "Evolutionary success requires contribution to later generations. Survival without reproduction need not increase an allele’s frequency.", "figure": null, "marks": 1, "level": "Core"}, {"n": 22, "topic": "Evolution", "obj": ["E05"], "stem": "An inherited thick covering reduces water loss but makes cooling harder. Which prediction about selection is most defensible?", "options": ["The covering must be advantageous everywhere.", "Its advantage can depend on temperature and water availability.", "Every individual will develop the covering when needed.", "The covering stops all future mutations."], "correct": 1, "why": "A trait can have costs and benefits; its effect on survival and reproduction depends on the environment.", "figure": null, "marks": 1, "level": "Core"}, {"n": 23, "topic": "Evolution", "obj": ["E09"], "stem": "In the tree, which pair shares the most recent common ancestor?", "options": ["K and L", "K and M", "M and N", "L and M"], "correct": 3, "why": "L and M meet at the most recent shared branching node. Horizontal label spacing is not evidence of relatedness.", "figure": "tree_mc", "marks": 1, "level": "Core"}, {"n": 24, "topic": "Evolution", "obj": ["E03", "E04"], "stem": "A new inherited allele is found before a population encounters a new environmental pressure. Which explanation is appropriate?", "options": ["Mutation can generate variation without anticipating future needs.", "The future environment selected the mutation in advance.", "All new alleles must improve survival.", "An acquired injury created the same allele in all gametes."], "correct": 0, "why": "Mutation is not directed toward a future need. Its effect on fitness depends on the later environment.", "figure": null, "marks": 1, "level": "Core"}, {"n": 25, "topic": "Rates", "obj": ["R01"], "stem": "Four collisions are described. Which meets both conditions for a successful reaction?", "options": ["Low energy and suitable orientation", "High enough energy and suitable orientation", "High enough energy and unsuitable orientation", "No contact but high speed"], "correct": 1, "why": "Successful collisions require enough energy to overcome the activation barrier and suitable orientation.", "figure": null, "marks": 1, "level": "Core"}, {"n": 26, "topic": "Rates", "obj": ["R02"], "stem": "Water is added to a reacting solution while temperature is held constant. What directly explains a lower initial collision rate after dilution?", "options": ["Each particle becomes larger.", "The activation barrier rises automatically.", "There are fewer reactant particles per unit volume.", "Every particle stops moving."], "correct": 2, "why": "Dilution lowers concentration, so reactant particles encounter one another less frequently per unit volume, all else equal.", "figure": null, "marks": 1, "level": "Core"}, {"n": 27, "topic": "Rates", "obj": ["R02"], "stem": "Equal masses of the same solid are used. One is a compact block and one is many small fragments. Which property chiefly accounts for a faster reaction of the fragments with excess solution?", "options": ["More total exposed surface", "More total mass", "A different chemical formula", "A higher temperature guaranteed by fragmentation"], "correct": 0, "why": "Fragmenting a fixed mass exposes more contact surface. It need not change temperature, chemical identity or total mass.", "figure": null, "marks": 1, "level": "Core"}, {"n": 28, "topic": "Rates", "obj": ["R02"], "stem": "A mixture reacts slowly because fresh solution is not reaching the solid surface. Gentle stirring increases the rate. Which explanation fits?", "options": ["Stirring creates extra reactant atoms.", "Stirring always lowers activation energy.", "Stirring makes the solid mass increase.", "Stirring brings reactant particles into contact with the surface more effectively."], "correct": 3, "why": "Mixing reduces local depletion and improves contact. It does not create atoms or act as a catalyst.", "figure": null, "marks": 1, "level": "Core"}, {"n": 29, "topic": "Rates", "obj": ["R02"], "stem": "A reaction forms 12 mg of product by 10 s and 30 mg by 20 s. What is its average rate during that interval?", "options": ["3.0 mg/s", "1.8 mg/s", "18 mg/s", "0.6 mg/s"], "correct": 1, "why": "Rate = change in product / elapsed time = (30 - 12)/(20 - 10) = 1.8 mg/s.", "figure": null, "marks": 1, "level": "Core"}, {"n": 30, "topic": "Heat", "obj": ["H01"], "stem": "A warm hand touches a colder metal rail. What is the net direction of thermal energy transfer at the contact?", "options": ["From rail to hand because cold flows", "No transfer because both are solids", "From hand to rail", "From both objects equally regardless of temperature"], "correct": 2, "why": "Net thermal energy transfer is from the warmer hand to the colder rail; cold is not a substance that flows.", "figure": null, "marks": 1, "level": "Core"}, {"n": 31, "topic": "Heat", "obj": ["H01"], "stem": "A warm object transfers energy to a detector across an evacuated gap. Which mechanism can transfer energy through that gap?", "options": ["Radiation", "Convection", "Conduction through air", "Bulk movement of water"], "correct": 0, "why": "Electromagnetic radiation can cross a vacuum. Conduction and convection require matter.", "figure": null, "marks": 1, "level": "Core"}, {"n": 32, "topic": "Heat", "obj": ["H01"], "stem": "Which observation provides direct evidence of convection?", "options": ["A metal handle warming along its length", "Light warming a surface", "Two solids exchanging energy at contact", "A coloured warm-water plume moving upward through cooler water"], "correct": 3, "why": "Convection involves bulk motion of fluid carrying energy. The plume shows fluid movement.", "figure": null, "marks": 1, "level": "Core"}, {"n": 33, "topic": "Genetics", "obj": ["G01"], "stem": "The diagram is a simplified animal cell. Structures A-D are shown.", "parts": [["Identify A-D.", 4, "A nucleus; B mitochondrion; C cytoplasm; D centrioles.", ["1 mark for each correct identification."], 4, false], ["For EACH of A-D, state one function.", 4, "A: nucleus contains most cellular DNA and helps regulate activity. B: mitochondrion supports aerobic respiration and ATP production. C: cytoplasm is the site of many chemical reactions. D: centrioles are components of animal-cell centrosomes involved in organising the spindle.", ["1 correct function for each labelled structure (4). Accept the Year 10 wording that centrioles help organise the spindle; the centrosome is the microtubule-organising centre."], 5, false]], "figure": "cell", "table": null, "marks": 8, "level": "Core"}, {"n": 34, "topic": "Genetics", "obj": ["G03", "G04"], "stem": "A student is building a short DNA model using the single strand 5′-GACTGA-3′.", "parts": [["Draw a six-base-pair DNA ladder containing this strand. Add the complementary bases and label the two sugar-phosphate backbones. Show opposite strand directions using 5′ and 3′ labels.", 3, "5′-GACTGA-3′ pairs with 3′-CTGACT-5′. The two sugar-phosphate backbones lie on the outside.", ["1 correct complementary sequence; 1 two labelled sugar-phosphate backbones; 1 opposite directions correctly labelled."], 0, true], ["Circle ONE complete nucleotide in your drawing and name its three components.", 2, "A nucleotide contains deoxyribose sugar, phosphate and one nitrogen-containing base.", ["1 correct unit circled (one sugar, one phosphate, one base); 1 all three components named."], 3, false], ["The ladder is a flattened model. Name the shape of DNA in three dimensions and identify the bonds between paired bases.", 1, "A double helix; hydrogen bonds between complementary bases.", ["1 for both statements."], 2, false], ["Write the full names of A, T, C and G.", 1, "Adenine, thymine, cytosine and guanine, respectively.", ["1 all four names correctly matched."], 2, false]], "figure": null, "table": null, "marks": 7, "level": "Core"}, {"n": 35, "topic": "Genetics", "obj": ["G02", "G05", "G11"], "stem": "A protein binds and stabilises a coloured pigment in plant petals. For one short segment of the protein, gene variant J specifies alanine-lysine-glycine-serine, while variant K specifies alanine-glutamate-glycine-serine. Both gene versions occupy the same position on homologous chromosomes.", "parts": [["State the term for J and K as different versions of the same gene, and explain the link between their DNA and amino-acid sequences.", 2, "J and K are alleles. Differences in DNA base sequence can change the information specifying amino-acid order.", ["1 alleles; 1 link from base sequence to amino-acid order."], 3, false], ["Explain how the amino-acid difference could reduce pigment binding.", 2, "A changed amino-acid sequence can alter protein folding or shape. The altered protein may bind the pigment less effectively.", ["1 possible altered shape; 1 linked reduction in protein function/pigment binding. Do not assume every substitution changes function."], 3, false], ["A third variant has a different DNA sequence but unchanged pigment-binding activity. Explain why a DNA change does not necessarily alter petal colour.", 1, "Some DNA changes leave the amino-acid sequence unchanged; others alter it without significantly affecting protein function.", ["1 valid explanation linked to unchanged function/phenotype."], 2, false]], "figure": null, "table": null, "marks": 5, "level": "Core"}, {"n": 36, "topic": "Genetics", "obj": ["G06"], "stem": "A dividing cell is sampled at five stages. DNA content is measured per cell, not per culture.", "parts": [["Identify which interval includes S phase. Explain the rise in DNA content.", 2, "The interval from sample A to B includes S phase; DNA is replicated, increasing the amount from 2 to 4 units.", ["1 A to B; 1 DNA replication."], 3, false], ["Describe the roles of G1 and G2.", 2, "G1 involves growth and normal activity before replication; G2 involves preparation/checking for division after replication.", ["1 correct G1 role; 1 correct G2 role."], 3, false], ["Explain why each cell at E has less DNA than the cell at D without losing genetic information needed by a daughter cell.", 1, "Replicated DNA has been separated into the two daughter cells, each receiving a complete set.", ["1 complete explanation about distribution of replicated sets, not destruction of half the genes."], 3, false], ["The onion-root micrograph above shows many cells at different stages of division. Explain how mitosis followed by cytokinesis supports root growth.", 1, "Mitosis distributes a copied chromosome set to each daughter nucleus; cytokinesis produces additional cells, increasing cell number as the root grows.", ["1 increased cell number through division. Equivalent genetic information is useful elaboration, not required for this mark. Do not credit merely increasing the size of one cell."], 3, false]], "figure": null, "table": [["Sample", "Observation", "DNA units per cell"], ["A", "Before DNA copying", "2"], ["B", "After DNA copying", "4"], ["C", "Before nuclear division", "4"], ["D", "Two nuclei in one cytoplasm", "4"], ["E", "Two separate daughter cells", "2 each"]], "marks": 6, "level": "Core"}, {"n": 37, "topic": "Genetics", "obj": ["G07", "G08", "G09"], "stem": "Two stages of mitosis in a model animal cell are shown. Its diploid number is 4.", "parts": [["Name stages P and Q and give one visible feature supporting each answer.", 2, "P is prophase: chromosomes have condensed and a spindle is forming. Q is metaphase: four replicated chromosomes align individually at the equator.", ["1 per correct stage with its supporting feature."], 3, false], ["Draw the next stage after Q. Label a spindle microtubule, a centromere and a separated chromosome. Show the correct number moving to each pole.", 3, "Draw anaphase with sister chromatids separated; four chromosomes move to each pole. Label spindle microtubule, centromere and a separated chromosome.", ["1 anaphase arrangement; 1 four chromosomes toward each pole; 1 all three labels accurately placed."], 0, true], ["List the four main mitotic phases in order, then describe what happens to nuclei during telophase.", 2, "Prophase, metaphase, anaphase, telophase. Nuclear envelopes form around the two separated chromosome sets.", ["1 complete correct order; 1 nuclear-envelope re-formation. Accept prometaphase as an additional stage."], 3, false]], "figure": "mitosis", "table": null, "marks": 7, "level": "Core"}, {"n": 38, "topic": "Genetics", "obj": ["G13", "G14"], "stem": "A simplified species has two homologous chromosome pairs, one long pair and one short pair. Use single lines for chromosomes; detailed meiotic stages are not required.", "parts": [["Draw a diploid starting cell and the four normal haploid products of meiosis. Show the chromosome types in every cell and label 2n and n.", 3, "Starting cell: two long and two short chromosomes, 2n = 4. Each of four products contains one long and one short chromosome, n = 2.", ["1 correct diploid starting set; 1 four products each with one of each chromosome type; 1 correct 2n = 4 and n = 2 labels."], 0, true], ["Explain how fertilisation using two of these gametes restores the diploid number.", 1, "Fusion combines one haploid set from each gamete, restoring two homologous pairs: 2 + 2 = 4.", ["1 combining two haploid sets to restore diploidy."], 2, false]], "figure": null, "table": null, "marks": 4, "level": "Core"}, {"n": 39, "topic": "Genetics", "obj": ["G10", "G11", "G12"], "stem": "Culture A stops dividing when its cells fill the available space. Culture B continues dividing after the space is filled. Cells from B also invade neighbouring tissue in a separate test.", "parts": [["Explain how mutations in cell-cycle control genes could produce the behaviour of culture B.", 2, "Mutations can disrupt proteins/signals that regulate division, allowing cells to divide when they should stop.", ["1 altered control genes/proteins; 1 loss of normal regulation causing excessive division."], 3, false], ["Identify the observation that supports malignancy rather than a benign tumour.", 1, "Cells invade neighbouring tissue.", ["1 invasion; excessive division alone does not distinguish benign from malignant."], 2, false], ["Define mutagen, name TWO distinct examples and briefly explain how ONE can cause a mutation.", 3, "A mutagen increases mutation probability. Examples include UV radiation and a DNA-damaging substance in tobacco smoke. UV can damage adjacent bases; if damage is not repaired correctly, copying can leave a changed DNA sequence.", ["1 definition; 1 two valid examples; 1 mechanism linking DNA damage or disruption to a lasting DNA change. Accept ionising radiation breaking DNA or viral insertion disrupting DNA. Generic radiation plus UV is one example; UV plus X-rays are two distinct named agents."], 4, false]], "figure": null, "table": null, "marks": 6, "level": "Core"}, {"n": 40, "topic": "Genetics", "obj": ["G18", "G19"], "stem": "The diagram is a schematic human karyotype. No other large chromosome changes are visible.", "parts": [["Identify the chromosome-number abnormality and calculate the total chromosome number.", 2, "There are three copies of chromosome 18 (trisomy 18); the total is 47 chromosomes.", ["1 extra chromosome 18; 1 47. Naming a syndrome is not required."], 2, false], ["State the sex-chromosome combination and its usual association in the typical XX/XY model.", 1, "XY, usually associated with male development.", ["1 XY with usual male association; this is not a statement about gender identity."], 2, false], ["Explain why this display cannot determine the DNA sequence of a particular gene.", 1, "A karyotype resolves whole chromosomes and some large changes, not individual DNA bases.", ["1 scale/resolution explanation."], 2, false]], "figure": "karyotype", "table": null, "marks": 4, "level": "Core", "calculations": {"0": {"fields": [["Total chromosome number", 47, "chromosomes"]], "marks": 1, "grouped": true}}}, {"n": 41, "topic": "Genetics", "obj": ["G21"], "stem": "In a fictional plant, a single autosomal gene controls pod surface. Smooth (S) is completely dominant to ridged (s). A homozygous smooth plant is crossed with a ridged plant; one offspring then self-pollinates.", "parts": [["Give the parental genotypes and the genotype of all first-generation offspring.", 2, "SS × ss gives all Ss offspring.", ["1 SS and ss; 1 all Ss."], 2, false], ["Construct a Punnett square for self-pollination of a first-generation offspring. State the genotype ratio with each genotype named.", 3, "Ss × Ss gives SS, Ss, Ss, ss. The genotype ratio is 1 SS : 2 Ss : 1 ss.", ["1 correct S/s gametes on both axes; 1 four correct cells; 1 labelled ratio."], 0, true], ["Give the expected fraction AND percentage of ridged offspring from that self-pollination.", 1, "1/4 = 25% ridged.", ["1 both equivalent expressions."], 2, false]], "figure": null, "table": null, "marks": 6, "level": "Core", "calculations": {"2": {"fields": [["Fraction", 0.25, "fraction"], ["Percentage", 25, "%"]], "marks": 1, "grouped": true}}}, {"n": 42, "topic": "Genetics", "obj": ["G24"], "stem": "The pedigree shows a fully penetrant single-gene autosomal condition. Assume no new mutation. Filled symbols show the condition; squares represent males and circles females.", "parts": [["Use a specific parent-child relationship to decide whether the condition is dominant or recessive.", 2, "Recessive: unaffected parents I-1 and I-2 have affected child II-2, which would not occur for a fully penetrant dominant condition without a new mutation.", ["1 recessive; 1 explicit I-1/I-2 to II-2 reasoning."], 3, false], ["Use A for the usual allele and a for the condition allele. State the genotypes of I-1, I-2 and II-2.", 2, "I-1 = Aa; I-2 = Aa; II-2 = aa.", ["1 both parents Aa; 1 child aa."], 2, false], ["Can the genotype of unaffected II-1 be determined uniquely? Give all possibilities and explain.", 2, "No: II-1 may be AA or Aa. Both are unaffected in this recessive model, so phenotype alone cannot distinguish them.", ["1 AA or Aa; 1 phenotype explanation."], 3, false], ["In a DIFFERENT family, a known autosomal dominant condition is caused by D. An affected parent and an unaffected partner have an unaffected child. Infer the affected parent’s genotype and explain.", 2, "The affected parent is Dd. The unaffected child is dd and received d from this parent; the parent also has D because they are affected.", ["1 Dd; 1 inference from transmission of d and affected phenotype."], 3, false]], "figure": "pedigree_core", "table": null, "marks": 8, "level": "Core"}, {"n": 43, "topic": "Genetics", "obj": ["G02"], "stem": "The diagram shows matching regions of two homologous autosomes before DNA replication. Letters mark alleles at corresponding gene positions. Only three genes are shown; the chromosomes carry many others.", "parts": [["Are B and b separate genes or alleles of the same gene? Explain using the positions shown.", 2, "They are alleles of the same gene: both occupy the corresponding position (locus) on the two homologous chromosomes.", ["1 alleles of the same gene; 1 corresponding loci used as evidence."], 3, false], ["Explain why these chromosomes are homologous even though they are not genetically identical.", 1, "They carry the same genes at corresponding positions but can carry different alleles, such as B and b.", ["1 same genes/loci and potentially different alleles."], 2, false]], "figure": "gene_map", "table": null, "marks": 3, "level": "Core"}, {"n": 44, "topic": "Evolution", "obj": ["E02", "E03", "E04", "G20"], "stem": "Seedlings from two wild populations differ in average height. When offspring from both populations are grown with the same light, water and nutrients, their average heights are similar.", "parts": [["Explain why the original height difference alone is insufficient evidence of genetic evolution.", 2, "Environmental conditions can affect height; a phenotypic difference alone does not demonstrate a change in inherited characteristics or allele frequencies across generations.", ["1 environmental influence; 1 missing inherited population change across generations."], 3, false], ["State one kind of additional evidence that could support inherited differences, and explain how alleles could produce such differences.", 2, "A persistent difference across generations in a controlled common environment, or evidence of different inherited alleles linked to height, would support inheritance. Alleles differ in DNA sequence and can affect protein function/regulation and phenotype.", ["1 suitable inheritance evidence; 1 link from allele/DNA difference to phenotype."], 3, false], ["Give one clear example of an acquired trait and one of an inherited trait. Explain the distinction.", 2, "A scar acquired after injury develops during life and is not inherited through gametes. An ABO blood group is influenced by alleles inherited from parents.", ["1 valid acquired example and non-inheritance explanation; 1 valid inherited example linked to parental alleles. Accept other sound examples."], 3, false]], "figure": null, "table": null, "marks": 6, "level": "Core"}, {"n": 45, "topic": "Evolution", "obj": ["E03", "E05"], "stem": "In a fictional annual plant, inherited flowering time varies. Some plants flower before a seasonal frost; others flower after it. In frosty years, early plants leave an average of 30 surviving seedlings per parent and late plants leave 8. Both forms are present before the first frost.", "parts": [["Explain how repeated frosty years could change the population over generations. Include the source of variation, selection pressure, reproductive success and inheritance.", 4, "There is pre-existing inherited variation in flowering time. Frost is a selection pressure; early-flowering plants leave more surviving offspring. These offspring inherit alleles associated with earlier flowering and can reproduce, so the frequency of those alleles/phenotypes can increase over generations.", ["1 existing heritable variation; 1 frost linked to differential reproductive success; 1 transmission of advantageous alleles; 1 increased allele/phenotype frequency over generations."], 6, false], ["If frost disappears, must early flowering remain favoured? Explain.", 1, "No. Its relative reproductive advantage may change when the environment and selection pressure change; other costs or benefits may become important.", ["1 conditional environmental explanation."], 2, false]], "figure": null, "table": null, "marks": 5, "level": "Core"}, {"n": 46, "topic": "Evolution", "obj": ["E01", "E08"], "stem": "Two populations of a freshwater snail once occupied connected wetlands. A long period of drying separated the wetlands. Much later, both snail populations are placed in the same suitable habitat. They still fail to mate because they respond to different mating signals.", "parts": [["Use this evidence to explain a possible allopatric speciation pathway. Explain why the drying event alone would not establish that speciation had occurred.", 4, "Drying created geographic isolation and reduced gene flow. Over generations inherited differences accumulated under different selection pressures (mutation/drift may also contribute). Divergent mating signals now cause reproductive isolation. The initial barrier only separated populations; reproductive isolation had not yet been demonstrated then.", ["1 geographic isolation/reduced gene flow; 1 divergence over generations; 1 later reproductive isolation linked to signals; 1 separation alone insufficient."], 6, false], ["If the original single species has become two species, state the effect on species diversity.", 1, "Species diversity/richness increases because there are now two species rather than one.", ["1 increase linked to an additional species."], 2, false]], "figure": "speciation", "table": null, "marks": 5, "level": "Core"}, {"n": 47, "topic": "Evolution", "obj": ["E09"], "stem": "The unscaled tree shows five fictional species. Dots mark branching nodes; no dates are supplied.", "parts": [["Which species is the closest relative of W? Explain using the tree.", 2, "X, because W and X share the most recent common ancestor.", ["1 X; 1 most recent shared node."], 3, false], ["A student says that Z evolved from the modern population of Y because their labels are next to each other. Correct the claim.", 1, "Y and Z share a common ancestor; the tree does not show one modern tip evolving from the other.", ["1 correct shared-ancestor interpretation."], 2, false], ["Can the tree show the exact year W and X diverged? Explain.", 1, "No. The tree has no time scale or dated nodes.", ["1 no with scale/date reason."], 2, false], ["Redraw the branching relationships with the order of W and X exchanged. Keep all evolutionary relationships unchanged.", 1, "Swap the two tips at their shared node; retain their sister relationship and all other branches.", ["1 topology retained after rotation."], 0, true]], "figure": "tree_sa", "table": null, "marks": 5, "level": "Core"}, {"n": 48, "topic": "Rates", "obj": ["R01", "R02"], "stem": "A student compares how quickly identical reactive tablets produce gas in water. The proposed trials are shown. The tablets have the same mass and composition.", "parts": [["Explain why the proposed comparison cannot isolate the effect of surface area.", 2, "Tablet form and water temperature are both changed, so either could cause a rate difference.", ["1 identifies two changed variables; 1 confounding explanation."], 3, false], ["Redesign the comparison to test surface area fairly. Name TWO controls and describe a quantitative rate measurement.", 2, "Use whole/crushed tablets at the same water temperature and volume (also same tablet mass/composition). Measure gas volume collected over a fixed interval or a gas-volume-versus-time curve.", ["1 two suitable controls; 1 quantitative rate measure with time."], 3, false], ["Explain the expected surface-area effect using collision theory.", 2, "Crushed material has more exposed surface for contact; more successful collisions can occur per second at that surface, increasing rate.", ["1 more contact surface; 1 greater successful-collision frequency."], 3, false], ["State the basic kinetic-theory idea about particle motion. Then use it and collision theory to explain why raising only the temperature could increase the reaction rate.", 3, "Particles are in continuous motion. Higher temperature increases their average kinetic energy and speed. A greater fraction of collisions has enough energy to overcome the activation barrier, increasing successful collisions per second.", ["1 particles in continuous motion; 1 increased average kinetic energy/speed; 1 greater fraction above the activation barrier linked to more successful collisions per second."], 4, false]], "figure": null, "table": [["Trial", "Tablet form", "Water temperature", "Water volume"], ["A", "Whole", "15 °C", "100 mL"], ["B", "Crushed", "35 °C", "100 mL"]], "marks": 9, "level": "Core"}, {"n": 49, "topic": "Rates", "obj": ["R02"], "stem": "A reaction produces a solid product that can be measured. A fixed amount of limiting reactant is used. All values below are cumulative product masses.", "parts": [["Plot product mass against time on the axes supplied. Include axis labels and units, and join the points with a sensible smooth curve.", 2, "Plot (0,0), (10,20), (20,34), (30,42), (40,46), (50,48), (60,48); time on x, mass on y.", ["1 all points within half a minor grid division (2.5 s and 2.5 mg); 1 correct labelled axes/units and a sensible non-decreasing curve that levels off."], 0, true], ["Calculate the average rate from 10 s to 30 s, showing working and units.", 2, "(42 - 20)/(30 - 10) = 22/20 = 1.1 mg/s.", ["1 correct change/change expression; 1 1.1 mg/s."], 3, false], ["A student uses the first recorded time at the final mass (50 s) and claims that half the product must have formed at 25 s. Evaluate this claim using the table.", 1, "The final mass is first recorded at 50 s, so half that recorded time is 25 s. Half the final mass is 24 mg, already exceeded at 20 s (34 mg); therefore the claim is false.", ["1 rejects claim using 25 s and evidence that 24 mg was exceeded before it. Do not assume the true finishing time is known more precisely than the sampling interval."], 3, false], ["Explain why the curve approaches a plateau rather than remaining equally steep.", 1, "Reactants are used up, reducing successful collisions; when limiting reactant is exhausted, no more product forms.", ["1 coherent depletion-to-plateau explanation."], 2, false]], "figure": null, "table": [["Time (s)", "0", "10", "20", "30", "40", "50", "60"], ["Product (mg)", "0", "20", "34", "42", "46", "48", "48"]], "marks": 6, "level": "Core", "calculations": {"1": {"fields": [["Average rate", 1.1, "mg/s"]], "marks": 1, "grouped": true}}}, {"n": 50, "topic": "Rates", "obj": ["R02"], "stem": "Steel labels in a humid plant nursery corrode. A technician coats some labels with an intact waterproof barrier that also blocks oxygen. The labels otherwise have identical conditions.", "parts": [["Explain why the intact coating slows rusting, referring to the reactants required.", 2, "Rusting requires iron, water and oxygen. The coating prevents water and oxygen from contacting the iron, reducing the reaction.", ["1 water and oxygen required; 1 barrier prevents their contact with iron."], 3, false], ["Predict where corrosion may begin if the coating is deeply scratched, and explain.", 1, "At the exposed scratch, where water and oxygen can reach iron.", ["1 location with contact explanation."], 2, false]], "figure": null, "table": null, "marks": 3, "level": "Core"}, {"n": 51, "topic": "Heat", "obj": ["H01"], "stem": "A metal spoon rests in hot soup. A nearby lamp shines on a dark tray, while warm soup circulates within the bowl.", "parts": [["Explain how the handle of the spoon becomes warm using a particle-level account of conduction.", 2, "Energy transfers from the hotter submerged end through the spoon by interactions between particles; in metal, mobile electrons also transfer energy. The bulk metal does not flow.", ["1 net hot-to-cool transfer through material; 1 particle interactions/electrons without bulk flow."], 3, false], ["Explain how heating part of the soup can establish a convection current.", 2, "Warmer soup expands/becomes less dense and rises; cooler denser soup sinks to replace it, circulating fluid and thermal energy.", ["1 warmer less-dense fluid rises; 1 cooler fluid sinks and circulation transfers energy."], 3, false], ["Explain how the lamp can warm the tray without touching it. State whether air is necessary for this transfer.", 2, "The tray absorbs electromagnetic radiation from the lamp, increasing its thermal energy. Radiation can travel through a vacuum, so air is not required.", ["1 absorption of electromagnetic radiation; 1 no medium required."], 3, false]], "figure": null, "table": null, "marks": 6, "level": "Core"}, {"n": 52, "topic": "Heat", "obj": ["H01", "H02"], "stem": "A class investigates whether a reflective cover reduces heating of identical dark blocks under a lamp. This is a planning task, not a replacement for the assessed practical.", "parts": [["Write a testable question and identify the independent variable and a measured dependent variable with units.", 2, "Does a reflective cover reduce the temperature rise of a block after 8 minutes under a lamp? Independent variable: cover present/absent. Dependent variable: temperature rise in °C after 8 minutes.", ["1 testable question with cover variable; 1 measurable dependent variable with units and fixed duration."], 3, false], ["Specify THREE controls and explain how independent repeat trials would improve the conclusion.", 2, "Control block material/mass, starting temperature and lamp distance/power (other valid controls accepted). Repeat with reset starting conditions and compare means and spread to assess variability.", ["1 three valid controls; 1 repeats assess variability/improve reliability rather than guarantee accuracy."], 4, false], ["Explain the expected result using radiation, and give one safety precaution for the lamp.", 2, "A reflective cover absorbs less incident radiation, so the block should warm less under otherwise identical conditions. Avoid touching the hot lamp; allow cooling before adjustment/use teacher-approved handling.", ["1 radiation/reflection linked to less warming; 1 appropriate precaution."], 3, false]], "figure": null, "table": null, "marks": 6, "level": "Core"}, {"n": 53, "topic": "Genetics", "obj": ["G23"], "stem": "A fictional gene has codominant alleles C¹ and C². A heterozygote produces both distinguishable pigments. Which observation supports codominance rather than blending?", "options": ["Only the C¹ pigment is detected.", "A new third pigment replaces both parental pigments.", "Neither pigment can be detected.", "Both parental pigments are separately detectable in the heterozygote."], "correct": 3, "why": "Codominance means both allelic effects are expressed; it is not simply an intermediate/blended phenotype.", "figure": null, "marks": 1, "level": "Extension"}, {"n": 54, "topic": "Genetics", "obj": ["G15", "G16"], "stem": "The diagram shows homologous chromosomes separating while each chromosome still has two joined sister chromatids. Which stage is shown?", "options": ["Anaphase I", "Metaphase II", "Anaphase II", "Telophase of mitosis"], "correct": 0, "why": "Homologues separate during anaphase I. Sister chromatids remain joined until meiosis II.", "figure": "meiosis_mc", "marks": 1, "level": "Extension"}, {"n": 55, "topic": "Genetics", "obj": ["G22", "G25"], "stem": "For an X-linked recessive trait in the typical XX/XY model, an affected daughter has genotype XᵃXᵃ. Assuming no new mutation, what must be true?", "options": ["Her father supplied a Y chromosome to her.", "Her mother must be affected.", "Each parent supplied an Xᵃ chromosome.", "Her father cannot be affected."], "correct": 2, "why": "The daughter receives one X from each parent. Her mother may be a carrier or affected; her father must supply Xᵃ.", "figure": null, "marks": 1, "level": "Extension"}, {"n": 56, "topic": "Evolution", "obj": ["E06"], "stem": "A seed bank uses a random handful of seeds from a large population to establish a new, isolated colony. An allele absent from that handful is absent from the colony. Which mechanism explains this initial difference?", "options": ["Directed mutation", "Founder effect", "Selection for larger seeds, necessarily", "Gene flow from the colony to the seed bank"], "correct": 1, "why": "A small random founding sample can omit alleles by chance; a fitness advantage is not required.", "figure": null, "marks": 1, "level": "Extension"}, {"n": 57, "topic": "Evolution", "obj": ["E07"], "stem": "Which event supplies evidence of gene flow between two plant populations?", "options": ["A pollen grain arrives but never fertilises an ovule.", "A seed visits a site but does not germinate.", "Both populations experience the same storm.", "Pollen from one population fertilises flowers in the other and contributes alleles to offspring."], "correct": 3, "why": "Alleles must enter the receiving population through reproduction. Movement without a reproductive contribution is insufficient.", "figure": null, "marks": 1, "level": "Extension"}, {"n": 58, "topic": "Rates", "obj": ["R03"], "stem": "Which change is expected when an enzyme catalyses a reaction at the same temperature?", "options": ["A lower activation-energy barrier", "An automatic rise in the temperature of every particle", "Permanent consumption of all enzyme molecules", "A greater amount of product regardless of reactant quantity"], "correct": 0, "why": "An enzyme provides a pathway with lower activation energy and is regenerated overall. It need not change the final product amount.", "figure": null, "marks": 1, "level": "Extension"}, {"n": 59, "topic": "Genetics", "obj": ["G15"], "stem": "Which event is absent from the normal sequence leading from the end of meiosis I through meiosis II?", "options": ["Spindle reorganisation", "Preparation for chromatid separation", "A second complete round of DNA replication", "Movement of chromosomes during division"], "correct": 2, "why": "DNA replication occurs once before meiosis I, not again between meiosis I and II.", "figure": null, "marks": 1, "level": "Extension"}, {"n": 60, "topic": "Evolution", "obj": ["E06", "E05"], "stem": "A neutral allele becomes common in a tiny population even though it does not affect survival or reproduction. Which explanation is most appropriate?", "options": ["All common alleles must be advantageous.", "Chance sampling across generations can change its frequency.", "Every individual changed its DNA deliberately.", "Natural selection always increases neutral alleles."], "correct": 1, "why": "Genetic drift can change neutral allele frequencies, particularly in small populations. Frequency alone does not demonstrate an advantage.", "figure": null, "marks": 1, "level": "Extension"}, {"n": 61, "topic": "Genetics", "obj": ["G26"], "stem": "A cell normally exports large amounts of a protein. After treatment, its ribosomes still assemble the protein, but protein accumulates near the rough endoplasmic reticulum instead of being exported.", "parts": [["Identify structures E and F in the cell detail.", 2, "E is rough endoplasmic reticulum; F is a ribosome attached to it.", ["1 rough ER; 1 ribosome."], 2, false], ["Distinguish the roles of ribosomes and rough endoplasmic reticulum in this cell.", 2, "Ribosomes join amino acids to make proteins. Rough ER supports processing and movement of many proteins destined for secretion or membranes.", ["1 ribosome synthesis; 1 rough ER processing/transport."], 3, false], ["Explain why the observations do not support a claim that protein synthesis has completely stopped.", 1, "Protein is still being assembled and accumulating; the disrupted step may be processing/transport rather than synthesis itself.", ["1 evidence-based distinction."], 2, false]], "figure": "rough_er", "table": null, "marks": 5, "level": "Extension"}, {"n": 62, "topic": "Genetics", "obj": ["G15", "G16", "G17"], "stem": "The model cell has 2n = 4. In the diagram, corresponding homologues are shown with matching sizes. Solid and outlined chromosomes distinguish parental origins.", "parts": [["Identify the stage shown and explain how its chromosome arrangement differs from metaphase of mitosis.", 2, "Metaphase I: homologous chromosomes align as pairs on opposite sides of the equator. In mitotic metaphase, replicated chromosomes align individually.", ["1 metaphase I; 1 paired versus individual alignment."], 3, false], ["Draw the two cells at metaphase II that could result from the orientation shown. Label sister chromatids, a centromere and spindle microtubules. Keep chromosome numbers correct.", 3, "Each of two cells contains two replicated chromosomes (one long, one short), aligned individually at its equator. The homologues have already separated.", ["1 two cells each with n = 2 replicated chromosomes; 1 individual metaphase II alignment consistent with supplied orientation; 1 all three labels correct."], 0, true], ["Name the stage that follows metaphase II and state what separates.", 1, "Anaphase II; sister chromatids separate.", ["1 both name and separating structures."], 2, false]], "figure": "meiosis_sa", "table": null, "marks": 6, "level": "Extension"}, {"n": 63, "topic": "Genetics", "obj": ["G15", "E03"], "stem": "During prophase I, two homologous replicated chromosomes carry the allele combinations AB and ab. A crossover occurs between the A and B loci in two non-sister chromatids.", "parts": [["Explain what crossing over exchanges and list the four resulting chromatid allele combinations after this single crossover.", 3, "Corresponding DNA segments are exchanged between non-sister chromatids of homologous chromosomes. The four combinations are AB, ab, Ab and aB.", ["1 correct non-sister/homologous structures; 1 corresponding DNA segment exchange; 1 all four combinations."], 4, false], ["Explain why this can increase variation without creating a new allele.", 1, "It creates new combinations of existing alleles; it need not change the base sequence to make a new allele.", ["1 recombination versus mutation distinction."], 2, false], ["List the four main phases of meiosis I in order, then the four of meiosis II. Beside each phase, give one key event. Use the table supplied.", 8, "Prophase I: homologues pair and crossing over can occur. Metaphase I: homologous pairs align at the equator. Anaphase I: homologues separate while sister chromatids stay joined. Telophase I: chromosomes reach opposite poles and the first nuclear division ends; nuclei may reform. Prophase II: spindles form again. Metaphase II: chromosomes align individually at the equator in each haploid cell. Anaphase II: sister chromatids separate. Telophase II: nuclei reform around four haploid sets. Cytokinesis normally produces four haploid cells.", ["For each division: 1 all four phase names in order; up to 3 for events (3 for four correct, 2 for three correct, 1 for two correct, 0 for zero/one). Total 4 per division, 8 overall. Do not require nuclear envelopes to re-form in telophase I in every species."], 0, false]], "figure": null, "table": null, "marks": 12, "level": "Extension"}, {"n": 64, "topic": "Genetics", "obj": ["G23"], "stem": "A fictional seed protein occurs in two distinguishable forms controlled by codominant alleles P¹ and P². P¹P¹ seeds contain only form 1; P²P² seeds contain only form 2; P¹P² seeds contain both forms.", "parts": [["Two plants whose seeds contain both forms are crossed. Construct a Punnett square and give the expected phenotype ratio.", 3, "P¹P² × P¹P² gives P¹P¹, P¹P², P¹P², P²P². Ratio: 1 form-1-only : 2 both forms : 1 form-2-only.", ["1 correct gametes; 1 four correct genotypes; 1 labelled phenotype ratio."], 0, true], ["A student describes the heterozygous seeds as containing a blended intermediate protein. Explain the error.", 1, "Both distinguishable protein forms are expressed; they are not replaced by one blended form.", ["1 both forms expressed rather than blending."], 2, false], ["Give the expected percentage of heterozygous offspring.", 1, "50%.", ["1 50%."], 1, false]], "figure": null, "table": null, "marks": 5, "level": "Extension", "calculations": {"2": {"fields": [["Heterozygous offspring", 50, "%"]], "marks": 1, "grouped": true}}}, {"n": 65, "topic": "Genetics", "obj": ["G22"], "stem": "A fictional X-linked recessive condition is caused by allele Xᵃ. Xᴬ is the usual allele. A carrier mother and an affected father have children. Use the typical XX/XY model, assume equal chances of X- and Y-bearing sperm, full penetrance and no new mutations.", "parts": [["State both parental genotypes and construct a Punnett square for this cross.", 3, "Mother XᴬXᵃ; father XᵃY. Outcomes: XᴬXᵃ, XᵃXᵃ, XᴬY, XᵃY, each with probability 1/4.", ["1 both parent genotypes; 1 correct gametes; 1 four correct combinations."], 0, true], ["Calculate separately the probability that a daughter is affected and the probability that a randomly selected child is an affected daughter. Explain the different denominators.", 2, "Among daughters, 1/2 are XᵃXᵃ. Among all children, 1/4 are affected daughters. The first probability is restricted to daughters; the second includes sons and daughters.", ["1 both probabilities correct; 1 denominators explained."], 3, false]], "figure": null, "table": null, "marks": 5, "level": "Extension", "calculations": {"1": {"fields": [["Affected among daughters", 0.5, "probability"], ["Affected daughter among all children", 0.25, "probability"]], "marks": 1, "grouped": true}}}, {"n": 66, "topic": "Genetics", "obj": ["G25", "G22"], "stem": "This family has a known X-linked recessive condition. Use Xᴬ and Xᵃ. Assume the typical XX/XY model, full penetrance and no new mutations. Filled symbols are affected; open symbols are unaffected.", "parts": [["Infer the genotypes of I-1, II-1 and III-1. Use the relationships shown.", 3, "I-1 = XᵃY; II-1 = XᴬXᵃ because she receives Xᵃ from her affected father but is unaffected; III-1 = XᵃY.", ["1 each correct genotype."], 3, false], ["Explain how the condition allele can pass from I-1 to III-1 even though there is no direct father-to-son X transmission.", 2, "I-1 passes Xᵃ to his daughter II-1; she can pass it to her son III-1, who receives Y from his own father.", ["1 grandfather-to-daughter X transmission; 1 mother-to-son X and father-to-son Y."], 3, false]], "figure": "pedigree_ext", "table": null, "marks": 5, "level": "Extension"}, {"n": 67, "topic": "Genetics", "obj": ["G21"], "stem": "In a fictional model, striped shells (S) are dominant to plain shells (s). Two heterozygotes are crossed. A separate, independently inherited trait has a probability of 1/2 of producing a curled edge. You may multiply probabilities for independent events.", "parts": [["A student gives P(SS) = 1/4 and P(SS given a striped offspring) = 1/4. Which probability needs correcting? Show the appropriate sample space.", 2, "The unconditional P(SS) = 1/4 is correct. For a striped offspring exclude ss: the equally likely outcomes are SS, Ss, Ss, so the conditional probability is 1/3.", ["1 distinguishes the unconditional and conditional samples; 1 restricted SS/Ss/Ss sample with 1/3."], 3, false], ["What is the probability a random offspring is plain AND has a curled edge? Show working.", 1, "P(plain) × P(curled) = 1/4 × 1/2 = 1/8 (12.5%).", ["1 correct product and result."], 2, false], ["An unknown striped individual is crossed with ss. Explain what observing even one plain offspring establishes about the unknown parent.", 1, "The striped parent must have contributed s, so it is Ss (assuming no mutation).", ["1 Ss supported by allele transmission."], 2, false]], "figure": null, "table": null, "marks": 4, "level": "Extension", "calculations": {"1": {"fields": [["Plain and curled", 0.125, "probability"]], "marks": 1, "grouped": true}, "0": {"fields": [["P(SS given striped)", 0.3333333333333333, "probability"]], "marks": 1, "grouped": true}}}, {"n": 68, "topic": "Evolution", "obj": ["E06"], "stem": "A captive insect population contains 100 diploid adults with 120 copies of allele A among 200 copies at a neutral gene. A random accident during transport leaves only 10 surviving adults. These have 6 copies of A among 20 copies. Survival was unrelated to this gene.", "parts": [["Calculate the frequency of A before and after the event, as percentages.", 2, "Before: 120/200 × 100 = 60%. After: 6/20 × 100 = 30%.", ["1 60%; 1 30%."], 3, false], ["Identify the type of genetic drift and explain why the result is not evidence that A became disadvantageous.", 2, "A population bottleneck: a sharp reduction leaves a small random sample. Survival was unrelated to the gene, so the frequency shift does not establish a fitness disadvantage.", ["1 bottleneck linked to reduction/random sampling; 1 no fitness inference because survival independent of allele."], 3, false], ["Contrast this event with a founder effect, and explain one possible consequence of lost genetic diversity.", 2, "A founder effect occurs when a few individuals establish a new population rather than a remnant surviving a reduction. Lost diversity can reduce the range of responses to future pressures, increasing vulnerability.", ["1 distinction about establishing a population; 1 qualified vulnerability explanation. Do not require extinction to be inevitable."], 3, false]], "figure": null, "table": null, "marks": 6, "level": "Extension", "calculations": {"0": {"fields": [["Before", 60, "%"], ["After", 30, "%"]], "marks": 2, "grouped": false}}}, {"n": 69, "topic": "Evolution", "obj": ["E05", "E06", "E07"], "stem": "In an isolated population, one allele has become rare. Conservation workers propose adding unrelated individuals from another population. A student claims, “If the newcomers arrive, genetic diversity is guaranteed to rise permanently.”", "parts": [["Explain what must happen for the newcomers to cause gene flow and how this could change the gene pool.", 2, "They must reproduce with members of the receiving population and contribute alleles to offspring; introduced alleles can alter frequencies and may increase variation.", ["1 reproductive contribution; 1 allele introduction/frequency effect."], 3, false], ["Give TWO reasons the claimed permanent increase is not guaranteed.", 2, "Newcomers may not reproduce or may carry no new alleles; introduced alleles may later be lost through drift or selected against.", ["1 per distinct valid reason."], 3, false], ["If a particular allele increases because its carriers leave more surviving offspring, identify the process and distinguish it from random drift.", 1, "Natural selection: a fitness-linked difference in reproductive success, rather than random sampling alone.", ["1 named process with distinction."], 2, false]], "figure": null, "table": null, "marks": 5, "level": "Extension"}, {"n": 70, "topic": "Rates", "obj": ["R03", "R01"], "stem": "Two pathways for the same reaction are described here. Both begin with reactants at 40 energy units and end with products at 15 units. The peak is 110 units without a catalyst and 65 units with a catalyst.", "parts": [["Calculate the activation energy for each pathway. Show your subtraction.", 2, "Uncatalysed: 110 - 40 = 70 units. Catalysed: 65 - 40 = 25 units.", ["1 each correct subtraction/result."], 3, false], ["Explain why the catalysed pathway can increase reaction rate at the same temperature.", 2, "The lower barrier means a greater fraction of collisions have enough energy to react, so the frequency of successful collisions increases without needing to raise average kinetic energy.", ["1 greater fraction exceeds lower barrier; 1 more successful collisions per unit time at same temperature."], 3, false], ["Does the catalyst change the difference in energy between reactants and products in this example? Use the values to justify your answer.", 1, "No. Both have 15 - 40 = -25 energy units; reactant and product levels are unchanged.", ["1 unchanged difference supported by numbers."], 2, false]], "figure": null, "table": null, "marks": 5, "level": "Extension", "calculations": {"0": {"fields": [["Uncatalysed activation energy", 70, "energy units"], ["Catalysed activation energy", 25, "energy units"]], "marks": 2, "grouped": false}}}, {"n": 71, "topic": "Rates", "obj": ["R03", "R02"], "stem": "An enzyme converts a substrate to a measurable product. Equal amounts of enzyme and substrate are used in each trial at the same pH. Rates are measured initially, before much substrate is used.", "parts": [["Explain the increase from 10 °C to 30 °C, then the decrease at 60 °C. Use both collision theory and enzyme structure.", 3, "From 10 to 30 °C, particles have greater average kinetic energy and more productive encounters occur. At 60 °C, many enzyme molecules denature, altering active-site shape and reducing substrate binding/catalysis.", ["1 increased kinetic energy/productive collision frequency; 1 denaturation/shape change; 1 reduced active-site function linked to lower rate."], 4, false], ["A fresh sample is heated to 60 °C and then cooled to 30 °C. Its rate remains low. Explain why cooling need not restore activity.", 1, "Denaturation can persist; cooling does not necessarily restore the enzyme’s original active-site shape.", ["1 persistent structural damage explanation."], 2, false], ["At 30 °C, increasing enzyme amount makes the reaction finish earlier, but the final product amount is unchanged. Explain BOTH observations.", 2, "More enzyme provides more active sites and increases rate while substrate is available. The same limiting amount of substrate sets the final product amount; enzyme is regenerated overall.", ["1 more active sites/faster conversion; 1 same limiting substrate/final product, not enzyme consumption."], 3, false]], "figure": null, "table": [["Temperature (°C)", "10", "30", "60"], ["Initial rate (mg/min)", "2", "8", "1"]], "marks": 6, "level": "Extension"}, {"n": 72, "topic": "Heat", "obj": ["H01", "H02"], "stem": "An insulated container keeps a frozen sample colder than an uninsulated container in a warm room. Its walls contain a vacuum gap and reflective surfaces. A solid support joins the inner and outer walls.", "parts": [["A student says the insulation “produces cold”. Correct this explanation and state the net direction of energy transfer.", 2, "The insulation reduces the rate of energy transfer into the colder sample; it does not produce cold. Net transfer is from the warmer room toward the colder contents.", ["1 slower energy gain rather than production of cold; 1 correct direction."], 3, false], ["Explain the different roles of the vacuum gap and reflective surfaces.", 2, "The vacuum removes matter needed for conduction/convection across the gap. Reflective surfaces reduce net radiative transfer by reflecting radiation/low emissivity.", ["1 vacuum limits conduction and convection; 1 reflective surfaces reduce radiation."], 3, false], ["Explain why the solid support still allows energy transfer, and propose a change that would reduce this transfer.", 2, "Conduction occurs through the solid bridge. Use a poorer conductor, a smaller cross-sectional area or a longer conduction path, while maintaining safe support.", ["1 conduction through support; 1 relevant material/geometric change."], 3, false]], "figure": "vacuum", "table": null, "marks": 6, "level": "Extension"}];
